import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks, TurnTotalUsage} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk, SendMessageParams, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';

it('sums usage across three provider calls', async () => {
  const usages: UsageMetadata[] = [
    {inputTokens: 2, outputTokens: 3, totalTokens: 5},
    {inputTokens: 7, outputTokens: 11, totalTokens: 18},
    {inputTokens: 13, outputTokens: 17, totalTokens: 30},
  ];
  let round = 0;
  const provider: AIProvider = {
    async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
      const current = round++;
      if (current < 2) yield {type: 'tool_use', toolCall: {id: `call-${current}`, name: 'lookup', input: {}}};
      yield {type: 'stop', stopReason: current < 2 ? 'tool_use' : 'end_turn', usage: usages[current]};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const registry = new ToolRegistry();
  registry.register({name: 'lookup', description: 'looks things up', inputSchema: {type: 'object'}}, async () => ({
    result: 'found',
  }));
  let reported: TurnTotalUsage | undefined;
  const hooks: OrchestratorHooks = {
    afterModelResponse: async (_session, _text, totalUsage) => void (reported = totalUsage),
  };
  const session: ChatSession = {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content: 'ask', timestamp: '2026-01-01T00:00:00.000Z'}],
  };

  await createChatOrchestrator(provider, new PromptBuilder({identity: 'assistant'}), registry, {hooks}).processMessage(
    session
  );

  expect({round, reported}).toEqual({round: 3, reported: {inputTokens: 22, outputTokens: 31, totalTokens: 53}});
});

